public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Collections.singletonList(nums[0]));
    } else {
        for (int i = 0; i < nums.length; i++) {
            List<List<Integer>> subPermutations = permute(Arrays.copyOfRange(nums, 0, i)
                    .concat(Arrays.copyOfRange(nums, i + 1, nums.length)));
            for (List<Integer> subPermission : subPermutations) {
                subPermission.add(0, nums[i]);
                result.add(subPermission);
            }
        }
    }
    return result;
}

public int findLargestSubstring(List<String> strings) {
    // Initialize a variable to store the largest substring
    int largestSubstring = 0;

    // Iterate over the strings
    for (String string : strings) {
        // Get the length of the string
        int stringLength = string.length();

        // Check if the string is longer than the current largest substring
        if (stringLength > largestSubstring) {
            // Store the string as the new largest substring
            largestSubstring = stringLength;
        }

        // Check if the inverted string is longer than the current largest substring
        if (stringLength > largestSubstring) {
            // Store the inverted string as the new largest substring
            largestSubstring = stringLength;
        }
    }

    // Return the largest substring
    return largestSubstring;
}

