public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to check if each n-tersection has been visited
    boolean[] visited = new boolean[n];

    // Create a queue to keep track of the n-tersections to be visited
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection coordinates and mark it as visited
        int[] current = queue.remove();
        visited[current[0] * n + current[1]] = true;

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Get the adjacent n-tersections and add them to the queue if they have not been visited
        for (int[] path : paths) {
            int currentRow = current[0] + path[0];
            int currentCol = current[1] + path[1];
            int currentIndex = currentRow * n + currentCol;
            if (!visited[currentIndex]) {
                queue.add(new int[]{currentRow, currentCol});
            }
        }
    }

    // If the starting n-tersection cannot be reached, return "cannot be travelled"
    return "cannot be travelled";
}

