public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        int midValue = nums[mid];

        if (midValue == target) {
            return mid;
        }

        if (nums[left] <= midValue) {
            if (target < midValue) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (target > midValue) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    // Step 1: Sort the array in ascending order
    Arrays.sort(arr);

    // Step 2: Calculate the threshold values (5% of the array size)
    int threshold = (int) (arr.length * 0.05);
    int topIndices = arr.length - threshold;
    int bottomIndices = threshold;

    // Step 3: Calculate the sum of the elements to be removed
    int sumToRemove = 0;
    for (int i = 0; i < topIndices; i++) {
        sumToRemove += arr[i];
    }
    for (int i = arr.length - 1; i >= bottomIndices; i--) {
        sumToRemove += arr[i];
    }

    // Step 4: Calculate the mean of the remaining elements
    double mean = 0;
    int count = 0;
    for (int i = topIndices; i < arr.length - bottomIndices; i++) {
        mean += arr[i];
        count++;
    }
    mean /= count;

    // Step 5: Return the mean
    return mean;
}

public boolean canArrange(int[] arr, int k) {
    // Initialize a hash map to keep track of the frequency of each element in the array
    HashMap<Integer, Integer> freq = new HashMap<>();
    for (int a : arr) {
        freq.put(a, freq.getOrDefault(a, 0) + 1);
    }

    // Iterate over the hash map and find the maximum frequency
    int maxFreq = 0;
    for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() > maxFreq) {
            maxFreq = entry.getValue();
        }
    }

    // Initialize a variable to keep track of the current sum
    int currSum = 0;
    for (int i = 0; i < arr.length / 2; i++) {
        // If the current sum is already divisible by k, we can skip this iteration
        if (currSum % k == 0) {
            continue;
        }

        // Find the element with the maximum frequency
        int maxFreqElement = -1;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() == maxFreq) {
                maxFreqElement = entry.getKey();
                break;
            }
        }

        // If no element with the maximum frequency exists, we cannot divide the array into pairs
        if (maxFreqElement == -1) {
            return false;
        }

        // Add the maximum frequency element to the current sum
        currSum += maxFreqElement;

        // Reduce the frequency of the maximum frequency element by 1
        freq.put(maxFreqElement, freq.get(maxFreqElement) - 1);
    }

    // If the current sum is divisible by k, we can divide the array into pairs
    if (currSum % k == 0) {
        return true;
    }
    return false;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create an adjacency list to represent the graph
    List<List<Integer>> graph = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Breadth-first search to determine the shortest path to the apples
    boolean[] visited = new boolean[n];
    int[] distance = new int[n];
    Arrays.fill(distance, -1);
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    distance[0] = 0;
    visited[0] = true;
    while (!queue.isEmpty()) {
        int curr = queue.remove();
        for (int neighbor : graph.get(curr)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                distance[neighbor] = distance[curr] + 1;
                queue.add(neighbor);
            }
        }
    }

    // Calculate the min time to collect all apples
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && distance[i] != -1) {
            minTime = Math.max(minTime, distance[i]);
        }
    }
    return minTime;
}

public String sortString(String s) {
    char[] result = new char[s.length()];
    int index = 0;

    while (index < s.length()) {
        // Find the smallest character in s that is greater than the last character in result
        char smallest = s.charAt(index);
        for (int i = index + 1; i < s.length(); i++) {
            if (s.charAt(i) > smallest && s.charAt(i) < result[result.length - 1]) {
                smallest = s.charAt(i);
            }
        }
        // Append the smallest character to result
        result[index++] = smallest;

        // Find the largest character in s that is smaller than the last character in result
        char largest = s.charAt(index);
        for (int i = index + 1; i < s.length(); i++) {
            if (s.charAt(i) < largest && s.charAt(i) > result[result.length - 1]) {
                largest = s.charAt(i);
            }
        }
        // Append the largest character to result
        result[index++] = largest;
    }

    return new String(result);
}

