int minCostClimbingStairs(int[] cost) {
  int currentMinCost = cost[0];
  int previousMinCost = cost[1];
  for (int i = 2; i < cost.length; i++) {
    int temp = currentMinCost;
    currentMinCost = Math.min(currentMinCost, previousMinCost);
    previousMinCost = temp + cost[i];
  }
  return Math.min(currentMinCost, previousMinCost);
}

