public boolean hasAllCodes(String s, int k) {
    // Initialize a set to store the unique substrings of length k
    Set<String> substrings = new HashSet<>();

    // Iterate over the characters of the input string
    for (int i = 0; i < s.length(); i++) {
        // Get the substring of length k starting from the current index
        String substr = s.substring(i, Math.min(s.length(), i + k));

        // If the substring is unique, add it to the set
        if (!substrings.contains(substr)) {
            substrings.add(substr);
        }

        // If the set already contains all the possible substrings of length k, return true
        if (substrings.size() == (int) Math.pow(2, k)) {
            return true;
        }
    }

    // If the set does not contain all the possible substrings of length k, return false
    return false;
}

