public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (true) {
        int x = 0;
        int y = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] != 0) {
                x = i;
                break;
            }
        }
        for (int i = 0; i < n; i++) {
            if (arr[i] != 0) {
                y = i;
                break;
            }
        }
        if (x == y) { // all elements are equal
            return minOperations;
        }
        arr[x] -= 1;
        arr[y] += 1;
        minOperations++;
    }
}

