public static boolean isPowerOfTwo(int n) {
    if (n == 0 || n == 1) {  // Special cases: 0 and 1 are both powers of 2
        return true;
    }
    int x = 1;
    while (x < n) {
        x *= 2;  // x = 2^x
        if (x == n) {  // If x is equal to n, then n is a power of 2
            return true;
        }
    }
    return false;  // If we reach here, n is not a power of 2
}

