    int n = mat[0].length;
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int curMax = 0;
                for (int k = i; k < m && curMax < n; k++) {
                    for (int l = j; l < n && curMax < m; l++) {
                        if (mat[k][l] == 0) {
