private static int countSquarePermutations(int[] A) {
        int count = 0;
        for (int i = 0; i < A.length; i++) {
            if (A[i] % 2 == 0) {
                count++;
            }
        }
        if (count == A.length) {
            return 1;
        }
        for (int i = 0; i < A.length; i++) {
            if (A[i] % 2 == 0 && isSquare(A[i])) {
                int j = i + 1;
                while (j < A.length && A[j] % 2 == 0 && !isSquare(A[j])) {
                    j++;
                }
                if (j == A.length) {
                    return 0;
                }
                int temp = A[i];
                A[i] = A[j];
                A[j] = temp;
            }
        }
        return countSquarePermutations(A);
    }

private static boolean isSquare(int n) {
        int k = (int) Math.round(Math.sqrt(n));
        return k * k == n;
    }

