public static List<String> centerSymmetricNumbers(int n) {
		List<String> result = new ArrayList<>();

		// handle n less than 1
		if (n <= 0) {
			return result;
		}

		// handle n equals 1
		if (n == 1) {
			result.add("0");
			result.add("1");
			result.add("8");
			return result;
		}

		// handle n greater than 1
		for (int i = 1; i <= n; i++) {
			int start = (int) Math.pow(10, n - 1) + i;
			int end = (int) Math.pow(10, n) - i;
			for (int j = start; j < end; j++) {
				String suffix = String.valueOf(j);
				if (isCenterSymmetric(suffix)) {
					result.add(suffix);
				}
			}
		}

		return result;
	}

private static boolean isCenterSymmetric(String s) {
		int len = s.length();
		for (int i = 0; i < len / 2; i++) {
			if (s.charAt(i) != s.charAt(len - 1 - i)) {
				return false;
			}
		}
		return true;
	}

public static boolean isBoomerang(int[][] points) {
    // Step 1: Sort the points based on the x-coordinate
    Arrays.sort(points, Comparator.comparingInt(point -> point[0]));

    // Step 2: Check if the points are in a counterclockwise order
    int area = getArea(points);
    if (area == 0) {
        return false;
    }

    // Step 3: Check if the points form a boomerang
    int i = 0;
    int j = points.length - 1;
    while (i < j) {
        if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
            return false;
        }
        i++;
        j--;
    }

    return true;
}

private static int getArea(int[][] points) {
    int area = 0;
    for (int i = 1; i < points.length - 1; i++) {
        area += (points[i][1] - points[0][1]) * (points[i][0] - points[points.length - 1][0]);
    }
    return area;
}

public static int findNthUglyNumber(int n) {
    int[] dp = new int[n+1];
    dp[1] = 1;
    int i2 = 1, i3 = 1, i5 = 1;
    for (int i = 2; i <= n; i++) {
        int nextUglyNumber = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
        dp[i] = nextUglyNumber;
        if (nextUglyNumber == dp[i2] * 2) i2++;
        if (nextUglyNumber == dp[i3] * 3) i3++;
        if (nextUglyNumber == dp[i5] * 5) i5++;
    }
    return dp[n];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() < 1) {
      return 0;
    }
    int longest = 0;
    int current = 0;
    for (int i = 0; i < s.length(); i++) {
      if (s.charAt(i) != s.charAt(i - 1) && longest < current) {
        longest = current;
      }
      if (s.charAt(i) == s.charAt(i - 1)) {
        current++;
      } else {
        current = 1;
      }
    }
    return longest;
  }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result, (a, b) -> {
        String aStr = a.toString();
        String bStr = b.toString();
        int minLen = Math.min(aStr.length(), bStr.length());
        for (int i = 0; i < minLen; i++) {
            if (aStr.charAt(i) > bStr.charAt(i)) {
                return 1;
            } else if (aStr.charAt(i) < bStr.charAt(i)) {
                return -1;
            }
        }
        return aStr.length() - bStr.length();
    });
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (!uniqueNums.contains(num)) {
            uniqueNums.add(num);
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
   int count = 0;
   for (int i = 1; i * i <= n; i++) {
      while (n - i * i >= 0) {
         count++;
         n -= i * i;
      }
   }
   return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversed = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        reversed.append(reversedWord.toString()).append(" ");
    }

    return reversed.toString().trim();
}
